/**
 * A workspace's past slugs, each held for `ORG_SLUG_HOLD_DAYS` from the
 * rename that retired it (see `docs/adr/0005-workspace-urls.md`). Rows are
 * not pruned when the hold lapses — `findOrgBySlug` filters on `retiredAt`
 * instead — but a rename back onto a slug the same org retired deletes its
 * row, ending that hold early.
 */
export const organizationRetiredSlugs = sqliteTable(
  "organization_retired_slugs",
  {
    id: idColumn(),
    orgId: text("org_id").notNull(),
    slug: text("slug").notNull(),
    retiredAt: text("retired_at").notNull(),
  },
  (table) => [
    index("organization_retired_slugs_slug_idx").on(table.slug),
    index("organization_retired_slugs_org_idx").on(table.orgId),
  ],
);

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;
export type OrganizationRetiredSlugRow =
  typeof organizationRetiredSlugs.$inferSelect;

