/**
 * Changes the workspace's URL. Per `docs/adr/0005-workspace-urls.md`: the
 * exact slug given is taken or refused, never suffixed; a refusal and a
 * no-op (renaming to the slug already in place) both leave the workspace
 * untouched; otherwise the old slug is retired for `ORG_SLUG_HOLD_DAYS` and
 * the change is announced once on `organization.slug_changed`, which the
 * audit log subscribes to.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const from = org.slug;
  if (from === input.slug) {
    return org;
  }

  if (!(await orgRepo.isSlugAvailableToOrg(input.slug, org.id))) {
    throw new InvalidSlugError(input.slug, "is already taken");
  }

  const renamed = await orgRepo.renameOrgSlug(org.id, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from,
    to: input.slug,
  });

  return renamed;
}

