/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, desc, eq, gt, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { addDays, now } from "@/lib/date";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizationRetiredSlugs,
  organizations,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp, toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

/** The instant before which a retirement has lapsed and the slug is free. */
function holdCutoff(): IsoTimestamp {
  return addDays(now(), -ORG_SLUG_HOLD_DAYS);
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to its workspace. Checked first as every org's current
 * slug, then — per ADR 0005 — as a slug retired by a rename within the last
 * `ORG_SLUG_HOLD_DAYS` days, so the old URL keeps working through the hold.
 * The only slug-to-org lookup in the app; every caller (the session layer,
 * `OrganizationService.resolveOrgBySlug`) goes through here for that reason.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = await findRetiredSlugOwner(slug);
  if (!retired || retired.retiredAt <= holdCutoff()) return null;

  const org = await findOrgById(retired.orgId);
  return org && org.archivedAt === null ? org : null;
}

/**
 * Any organization — live or archived — currently holding `slug` as its
 * current slug. Used for rename availability, where a deleted workspace
 * still blocks the slug (ADR 0005, rule 2).
 */
export async function findOrgByCurrentSlugAny(
  slug: string,
): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * The most recent retirement of `slug`, regardless of whether its hold has
 * lapsed — callers decide what "still held" means for their purpose (see
 * `holdCutoff`). `null` when the slug has never been retired.
 */
export async function findRetiredSlugOwner(
  slug: string,
): Promise<{ orgId: OrgId; retiredAt: IsoTimestamp } | null> {
  const row = getDb()
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .orderBy(desc(organizationRetiredSlugs.retiredAt))
    .get();
  if (!row) return null;
  return { orgId: brandId<OrgId>(row.orgId), retiredAt: brandStamp(row.retiredAt) };
}

/**
 * Whether `slug` may become `orgId`'s new current slug: unavailable while
 * any other workspace — live or archived — holds it as current, or holds it
 * retired within its hold window. A slug `orgId` itself retired, or once
 * retired, is available to `orgId` at any time (ADR 0005, rule 2).
 */
export async function isSlugAvailableToOrg(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const currentHolder = await findOrgByCurrentSlugAny(slug);
  if (currentHolder && currentHolder.id !== orgId) return false;

  const retiredOwner = await findRetiredSlugOwner(slug);
  if (!retiredOwner || retiredOwner.orgId === orgId) return true;

  return retiredOwner.retiredAt <= holdCutoff();
}

/**
 * Applies a rename: ends the retirement `newSlug` may hold for this same
 * workspace (ADR 0005, rule 4), retires the slug being replaced, and writes
 * the new current slug. Callers must have already established the rename is
 * permitted and `newSlug` is available.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  newSlug: string,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  db.delete(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.slug, newSlug),
        eq(organizationRetiredSlugs.orgId, orgId),
      ),
    )
    .run();

  db.insert(organizationRetiredSlugs)
    .values({ id: newId(), orgId, slug: current.slug, retiredAt: stamp })
    .run();

  const row = db
    .update(organizations)
    .set({ slug: newSlug, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

/**
 * Settings and profile patch. `slug` is accepted for the "change workspace
 * URL" form: the form validates the slug with `slugSchema` before it gets
 * here, so the column is written as given.
 */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput & { readonly slug?: string },
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. Includes
 * slugs still held in retirement — ADR 0005 has creation suffix away from
 * those exactly as it does from a current slug.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();

  const current = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const cutoff = holdCutoff();
  const retired = db
    .select({ slug: organizationRetiredSlugs.slug })
    .from(organizationRetiredSlugs)
    .where(
      and(
        like(organizationRetiredSlugs.slug, `${prefix}%`),
        gt(organizationRetiredSlugs.retiredAt, cutoff),
      ),
    )
    .all();

  return [...current, ...retired].map((row) => row.slug);
}

