import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("renamesmoke");
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlug smoke", () => {
  it("renames, retires the old slug, resolves both, and refuses a conflict", async () => {
    const seen: { from: string; to: string }[] = [];
    const off = subscribe("organization.slug_changed", (p) => {
      seen.push({ from: p.from, to: p.to });
    });

    const other = await createTenant("othersmoke");

    const renamed = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "renamesmoke-new",
    });
    expect(renamed.slug).toBe("renamesmoke-new");
    expect(seen).toEqual([{ from: "renamesmoke", to: "renamesmoke-new" }]);

    const byOld = await resolveOrgBySlug("renamesmoke");
    expect(byOld?.id).toBe(tenant.org.id);
    const byNew = await resolveOrgBySlug("renamesmoke-new");
    expect(byNew?.id).toBe(tenant.org.id);

    // Another org can't take the still-held old slug.
    await expect(
      renameOrganizationSlug(other.actors.admin, {
        orgId: other.org.id,
        slug: "renamesmoke",
      }),
    ).rejects.toThrow();

    // No-op rename changes nothing and publishes nothing.
    const before = seen.length;
    const noop = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "renamesmoke-new",
    });
    expect(noop.slug).toBe("renamesmoke-new");
    expect(seen.length).toBe(before);

    // Rename back to the retired slug ends its retirement and retires the
    // one being replaced.
    const back = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "renamesmoke",
    });
    expect(back.slug).toBe("renamesmoke");

    const retiredNew = await orgRepo.findRetiredSlugOwner("renamesmoke-new");
    expect(retiredNew?.orgId).toBe(tenant.org.id);
    const retiredOld = await orgRepo.findRetiredSlugOwner("renamesmoke");
    // Still has a historical row, but it's expired/reclaimed: since this org
    // now holds it current again, availability to itself must hold regardless.
    expect(retiredOld).not.toBeNull();

    // Now the other org CAN take "renamesmoke-new" since nobody holds it
    // live and the only hold on it belongs to tenant.org, not a blocker for
    // third parties only while held — but the hold hasn't expired, so this
    // must still be refused.
    await expect(
      renameOrganizationSlug(other.actors.admin, {
        orgId: other.org.id,
        slug: "renamesmoke-new",
      }),
    ).rejects.toThrow();

    off();
  });

  it("refuses an org:update-insufficient actor (viewer) and changes nothing", async () => {
    await expect(
      renameOrganizationSlug(tenant.actors.viewer, {
        orgId: tenant.org.id,
        slug: "whatever-slug",
      }),
    ).rejects.toThrow();
  });
});

